
/* ================================================================== *
 *  selfTest — headless verification.  Values labelled (derive) come   *
 *  from REF, generated by gen_tables.py from refvals.txt, which is    *
 *  derive.py's printed output (scipy brentq, quad, solve_ivp at rtol  *
 *  1e-13), read in full.                                              *
 * ================================================================== */
function makeShot(W, H){
  const ops = []; let Mx = [1, 0, 0, 1, 0, 0]; const stack = [];
  const st2 = {font: '10px x', align: 'left', base: 'alphabetic'};
  const mul = (A, B) => [A[0] * B[0] + A[2] * B[1], A[1] * B[0] + A[3] * B[1], A[0] * B[2] + A[2] * B[3],
                         A[1] * B[2] + A[3] * B[3], A[0] * B[4] + A[2] * B[5] + A[4], A[1] * B[4] + A[3] * B[5] + A[5]];
  const app = (x, y) => [Mx[0] * x + Mx[2] * y + Mx[4], Mx[1] * x + Mx[3] * y + Mx[5]];
  const fsz = () => { const m = /([\d.]+)px/.exec(st2.font); return m ? parseFloat(m[1]) : 10; };
  let pend = null;
  const ctx = {ops,
    save(){ stack.push({M: Mx.slice(), f: st2.font, a: st2.align, b: st2.base}); },
    restore(){ const s = stack.pop(); if(s){ Mx = s.M; st2.font = s.f; st2.align = s.a; st2.base = s.b; } },
    translate(x, y){ Mx = mul(Mx, [1, 0, 0, 1, x, y]); },
    rotate(r){ const c = Math.cos(r), s3 = Math.sin(r); Mx = mul(Mx, [c, s3, -s3, c, 0, 0]); },
    scale(x, y){ Mx = mul(Mx, [x, 0, 0, y, 0, 0]); }, setTransform(){ Mx = [1, 0, 0, 1, 0, 0]; },
    beginPath(){ pend = null; }, moveTo(){}, lineTo(){ if(!pend) pend = {n: 0}; }, closePath(){},
    rect(){ if(!pend) pend = {n: 0}; pend.n++; }, arc(){ if(!pend) pend = {n: 0}; pend.n++; },
    fill(){ if(pend) ops.push({op: 'fill', n: pend.n || 1}); },
    stroke(){ ops.push({op: 'stroke'}); }, clip(){},
    fillRect(x, y, w, hh){ ops.push({op: 'fill', n: 1, bb: [x, y, x + w, y + hh], style: ctx.fillStyle}); },
    strokeRect(){ ops.push({op: 'stroke'}); }, clearRect(){},
    fillText(t, x, y){
      const w = ('' + t).length * fsz() * 0.52, fh = fsz() * 1.15;
      const lx = st2.align === 'center' ? x - w / 2 : (st2.align === 'right' ? x - w : x);
      const ly = st2.base === 'top' ? y : (st2.base === 'middle' ? y - fh / 2 : (st2.base === 'bottom' ? y - fh : y - fh * 0.8));
      const cs = [[lx, ly], [lx + w, ly], [lx, ly + fh], [lx + w, ly + fh]].map(c2 => app(c2[0], c2[1]));
      const xs = cs.map(c2 => c2[0]), ys = cs.map(c2 => c2[1]);
      ops.push({op: 'text', t: '' + t, bb: [Math.min.apply(0, xs), Math.min.apply(0, ys), Math.max.apply(0, xs), Math.max.apply(0, ys)]});
    },
    strokeText(){}, setLineDash(){},
    measureText(t){ return {width: ('' + t).length * fsz() * 0.52}; },
    createLinearGradient(){ return {addColorStop(){}}; }
  };
  let _fill = '#000';
  Object.defineProperty(ctx, 'fillStyle', {get: () => _fill, set: v => _fill = '' + v});
  for(const kk of ['strokeStyle', 'lineWidth', 'globalAlpha', 'lineJoin', 'lineCap']){ let v2; Object.defineProperty(ctx, kk, {get: () => v2, set: x => v2 = x}); }
  Object.defineProperty(ctx, 'font', {get: () => st2.font, set: v => st2.font = '' + v});
  Object.defineProperty(ctx, 'textAlign', {get: () => st2.align, set: v => st2.align = '' + v});
  Object.defineProperty(ctx, 'textBaseline', {get: () => st2.base, set: v => st2.base = '' + v});
  return ctx;
}

function selfTest(){
  let pass = 0, fail = 0;
  const ok = (c, name) => { if(c) pass++; else { fail++; console.log('FAIL — ' + name); } };
  const eq = (a, b, name) => ok(a === b, name + ' [' + a + ' vs ' + b + ']');
  const close = (a, b, tol, name) => ok(Math.abs(a - b) <= tol, name + ' [' + a + ' vs ' + b + ']');
  const angc = (a, b, tol, name) => { let d = (a - b) % TAU; if(d > PI) d -= TAU; if(d < -PI) d += TAU;
    ok(Math.abs(d) <= tol, name + ' [' + a + ' vs ' + b + ']'); };
  const rel = (a, b, t, name) => ok(Math.abs(a - b) <= t * Math.abs(b || 1),
    name + ' [' + a + ' vs ' + b + ', rel ' + (Math.abs(a - b) / Math.abs(b || 1)).toExponential(2) + ']');
  const T0 = Date.now();
  const stSave = Object.assign({}, ST);
  function withState(over, fn){
    const simSave = JSON.parse(JSON.stringify(SIM));
    const o = Object.assign({}, over); const frames = o.frames, tset = o.t;
    delete o.frames; delete o.t;
    Object.assign(ST, DEFAULTS, o); simReset();
    if(frames){ setRunning(true); for(let k = 0; k < frames; k++) runStep(); }
    if(tset !== undefined) SIM.t = tset;
    try{ return fn(); } finally{ Object.assign(ST, stSave); Object.assign(SIM, simSave); }
  }

  /* ---------- 0. the shared helpers, and the units ---------- */
  ok(plain('&Delta;x &theta; &#955; M&#8321;') === 'Δx θ λ M₁', 'plain() decodes named, capital and numeric entities');
  ok(plain('a<sub>B</sub>b') === 'aBb', 'plain() strips tags');
  ok(ticksFor(0.8, 0.2, 5).length === 1 && ticksFor(0.2, 0.8, 5).length >= 3, 'axes() range-sort is what rescues an inverted axis');
  { let threw = false; try{ toRgb('nope'); }catch(e){ threw = true; } ok(threw, 'toRgb throws on garbage'); }
  { const stub = {beginPath(){}, moveTo(){}, lineTo(){}, stroke(){}, save(){}, restore(){}, setLineDash(){}};
    const bb = box(100, 100, 200, 100); POLY_SEGS = [];
    polyline(stub, bb, [-1, 2], [0.5, 0.5], 0, 1, 0, 1, '#fff', 1);
    ok(POLY_SEGS.length === 4 && Math.abs(POLY_SEGS[0] - bb.x) < 1e-9 && Math.abs(POLY_SEGS[2] - bb.x1) < 1e-9,
       'polyline clips a both-ends-outside segment to the frame edges');
    POLY_SEGS = []; }
  close(90 * DEG, PI / 2, 1e-15, 'DEG converts degrees INTO radians (90 DEG = pi/2)');
  eq(AU_KM, 149597870.7, '1 AU in km (IAU 2012)');
  eq(YR_S, 31557600, 'the Julian year in seconds');
  eq(GM_SUN, 1.32712440042e20, 'GM_sun (Wikipedia, as lagrange_points.html)');
  rel(K_SUN, REF.K_SUN, 1e-15, 'K = GM_sun yr^2/AU^3 (derive)');
  rel(KMS, REF.KMS, 1e-15, '1 AU/yr in km/s (derive)');
  rel(periodOf(1, K_SUN), REF.T1, 1e-15, 'a test body at 1 AU takes 365.2569 d (derive)');
  rel(auYrToKms(Math.sqrt(K_SUN)), REF.vc1, 1e-14, 'circular speed at 1 AU = 29.7847 km/s (derive)');
  rel(klConst(1), REF.kepler_const, 1e-15, 'T^2/a^3 = 4 pi^2/GM for our Sun (derive)');
  close(auYrToKms(1) * YR_S, AU_KM, 1e-6, 'the km/s conversion is one AU per Julian year');
  close(kmsToAuYr(auYrToKms(3.7)), 3.7, 1e-15, '... and it inverts');

  /* ---------- A. Kepler's equation ---------- */
  { let worstE = 0, worstRes = 0, maxIt = 0;
    for(const c of REF.kepler){
      const s = keplerSolve(c.M, c.e);
      worstE = Math.max(worstE, Math.abs(s.E - c.E));
      const turns = Math.round(c.M / TAU);
      worstRes = Math.max(worstRes, Math.abs((s.E - TAU * turns) - c.e * Math.sin(s.E - TAU * turns) - (c.M - TAU * turns)));
      maxIt = Math.max(maxIt, s.it);
      rel(trueFromE(s.E, c.e), c.nu, 1e-11, 'nu(E) at M = ' + c.M + ', e = ' + c.e + ' (derive)');
    }
    ok(worstE < 1e-12, 'E matches scipy brentq at all ' + REF.kepler.length + ' (M, e) pairs (worst ' + worstE.toExponential(2) + ', derive ' + REF.kepler_worst.toExponential(2) + ')');
    ok(worstRes < 1e-14, 'the residual E - e sin E - M is at machine precision (' + worstRes.toExponential(2) + ')');
    ok(maxIt <= 20, 'never more than 20 Newton/bisection steps (' + maxIt + ', derive 15)'); }
  /* the safeguard must not stall: the naive "strictly inside the bracket" rule took 51 steps here */
  ok(keplerSolve(0.3, 0.99).it <= 8, 'e = 0.99, M = 0.3 converges in a handful of steps (' + keplerSolve(0.3, 0.99).it + ')');
  close(keplerSolve(1e-9, 0.2).E, 1e-9 / 0.8, 1e-20, 'small M: E -> M/(1-e) at e = 0.2 (derive)');
  close(keplerSolve(1e-9, 0.9).E, 1e-8, 1e-19, 'small M: E -> M/(1-e) at e = 0.9 (derive)');
  eq(keplerSolve(2.7, 0).E, 2.7, 'a circle needs no iteration: E = M');
  eq(keplerSolve(2.7, 0).it, 0, '... and takes no steps');
  { let worst = 0;
    for(let k = 0; k < 97; k++){ const nu = -PI + TAU * k / 97;
      for(const e of [0, 0.03, 0.4, 0.8, 0.97]){
        const E = eccFromTrue(nu, e);
        worst = Math.max(worst, Math.abs(trueFromE(E, e) - nu)); } }
    ok(worst < 1e-12, 'nu -> E -> nu round-trips over the whole orbit (' + worst.toExponential(2) + ')'); }
  { let worst = 0;
    for(const e of [1.2, 2.5, 8]) for(const M of [-9, -1, -0.01, 0.01, 1, 9]){
      const H = keplerH(M, e);
      worst = Math.max(worst, Math.abs(e * Math.sinh(H) - H - M) / (1 + Math.abs(M))); }
    ok(worst < 1e-14, 'the hyperbolic solver satisfies e sinh H - H = M (' + worst.toExponential(2) + ')'); }
  /* PhET's 0.01-rad stop, re-measured here */
  { const phetE = (M, e) => { let t = M, i = 1, n = 0;
      while(Math.abs(i) > PHET.NEWTON_TOL && n < 60){ i = (t - e * Math.sin(t) - M) / (1 - e * Math.cos(t)); t -= i; n++; } return t; };
    for(const key of ['0.3333', '0.9670']){
      const R = REF.phet_tol[key]; let worst = 0;
      for(let k = 0; k < 2001; k++){ const M = TAU * k / 2001; worst = Math.max(worst, Math.abs(phetE(M, R.e) - keplerE(M, R.e))); }
      rel(worst, R.worst, 1e-6, 'PhET\'s 0.01-rad stop leaves ' + R.worst.toExponential(2) + ' rad at e = ' + R.e + ' (derive)'); }
    const e = 1 / 3, a = 1.5, b = a * Math.sqrt(1 - e * e); let wp = 0;
    for(let k = 0; k < 2001; k++){ const M = TAU * k / 2001, Ep = phetE(M, e), Et = keplerE(M, e);
      wp = Math.max(wp, Math.hypot(a * (Math.cos(Ep) - Math.cos(Et)), b * (Math.sin(Ep) - Math.sin(Et)))); }
    rel(wp, REF.phet_pos_err_au, 1e-6, 'and puts the planet up to 2.4e-5 AU = 3,559 km off on the default orbit (derive)');
    ok(wp * AU_KM > 3000, '... which is thousands of km, not metres'); }

  /* ---------- B. the conic from a state ---------- */
  for(const name in REF.els){
    const R = REF.els[name], mu = K_SUN * R.M, tag = name + ': ';
    const el = conicFromState(R.x, R.y, R.vx, R.vy, mu);
    eq(el.kind, 'ellipse', tag + 'an ellipse');
    rel(el.a, R.a, 1e-13, tag + 'a from vis-viva (derive)');
    close(el.e, R.e, 1e-13, tag + 'e from the eccentricity vector (derive)');
    angc(el.w, R.w, 1e-12, tag + 'the periapsis direction (derive)');
    eq(el.dir, R.dir, tag + 'the sense of travel');
    rel(el.T, R.T, 1e-13, tag + 'T = 2 pi sqrt(a^3/mu) (derive)');
    rel(el.b, R.b, 1e-13, tag + 'b (derive)'); rel(el.c, R.c, 1e-13, tag + 'c (derive)');
    rel(el.q, R.q, 1e-13, tag + 'periapsis (derive)'); rel(el.Q, R.Q, 1e-13, tag + 'apoapsis (derive)');
    close(el.M0, R.M0, 1e-12, tag + 'M0 (derive)'); close(el.nu0, R.nu0, 1e-12, tag + 'nu0 (derive)');
    rel(el.h, R.h, 1e-13, tag + 'h (derive)'); rel(el.energy, R.energy, 1e-13, tag + 'the energy (derive)');
    /* identities, computed a second way */
    rel(el.e, Math.sqrt(1 + 2 * el.energy * el.h * el.h / (mu * mu)), 1e-12, tag + 'e = sqrt(1 + 2 eps h^2/mu^2)');
    rel(Math.abs(el.h), el.n * el.a * el.b, 1e-13, tag + '|h| = n a b');
    rel(el.b, el.a * Math.sqrt(1 - el.e * el.e), 1e-15, tag + 'b = a sqrt(1 - e^2)');
    rel(el.p, el.a * (1 - el.e * el.e), 1e-13, tag + 'p = a(1 - e^2)');
    /* the state at t against solve_ivp */
    let worst = 0;
    for(const p of R.pts){
      const s = stateOnConic(el, p.t);
      worst = Math.max(worst, Math.hypot(s.x - p.x, s.y - p.y) / el.a);
      /* a velocity COMPONENT passes through zero, so the tolerance is on the speed scale,
         not on the component (Known-bad: an absolute tolerance on a vanishing quantity) */
      const vs = Math.max(1e-3, Math.hypot(p.vx, p.vy));
      close(s.vx, p.vx, 2e-9 * vs, tag + 'vx at t = ' + fmt(p.t, 3) + ' (solve_ivp)');
      close(s.vy, p.vy, 2e-9 * vs, tag + 'vy at t = ' + fmt(p.t, 3) + ' (solve_ivp)');
      /* vis-viva must hold at every one of them */
      rel(0.5 * (s.vx * s.vx + s.vy * s.vy) - mu / Math.hypot(s.x, s.y), el.energy, 1e-12, tag + 'the energy is conserved at t = ' + fmt(p.t, 3));
    }
    ok(worst < 1e-9, tag + 'the Kepler position tracks solve_ivp over 2.3 periods (' + worst.toExponential(2) + ' of a)');
    /* the elements are constants of the motion: rebuild them from a later state */
    const s2 = stateOnConic(el, 0.61 * el.T), el2 = conicFromState(s2.x, s2.y, s2.vx, s2.vy, mu);
    rel(el2.a, el.a, 1e-12, tag + 'a recovered from the state 0.61 T later');
    close(el2.e, el.e, 1e-12, tag + 'e recovered'); angc(el2.w, el.w, 1e-10, tag + 'the periapsis direction recovered');
    /* the period really is the period */
    const s3 = stateOnConic(el, el.T);
    close(s3.x, R.x, 1e-9, tag + 'back to the start after one period (x)');
    close(s3.y, R.y, 1e-9, tag + 'back to the start after one period (y)');
  }
  { /* a SMALL eccentricity must survive: PhET's own target orbits are Venus 0.0068, Earth
       0.0167 and Jupiter 0.0484, so a "treat it as a circle" threshold anywhere near 0.1
       would flatten them all (the mutation sweep found nothing pinning this) */
    for(const [e0, a0] of [[0.0068, 0.7], [0.0167, 1.0], [0.0484, 5.2]]){
      const mu = K_SUN, q = a0 * (1 - e0);
      const el = conicFromState(q, 0, 0, Math.sqrt(mu * (1 + e0) / q), mu);
      rel(el.e, e0, 1e-12, 'e = ' + e0 + ' is kept, not rounded to a circle');
      rel(el.a, a0, 1e-12, '... with a = ' + a0);
      close(el.w, 0, 1e-9, '... and periapsis where it was launched');
    } }
  { /* conicPoint draws the orbit, the sectors and the apsis markers, and until the sweep
       flagged it nothing tested it: it must agree with the state at the time nu is reached */
    const el = klOrbit(2, 0, 0, V_DEF, 1, false);
    let worst = 0;
    for(let k = 0; k < 24; k++){
      const nu = TAU * k / 24, t = (meanFromTrue(nu, el.e) - el.M0) / el.n;
      const s = klStateAt(el, t), p = conicPoint(el, nu);
      worst = Math.max(worst, Math.hypot(p[0] - s.x, p[1] - s.y));
    }
    ok(worst < 1e-12, 'conicPoint(nu) is the state at the time that nu is reached (' + worst.toExponential(2) + ')');
    const pq = conicPoint(el, 0), pQ = conicPoint(el, PI);
    rel(Math.hypot(pq[0], pq[1]), el.q, 1e-13, '... periapsis at nu = 0');
    rel(Math.hypot(pQ[0], pQ[1]), el.Q, 1e-13, '... apoapsis at nu = pi');
    const poly = klSectorPoly(el, 0.3, 1.1, 8);
    ok(poly.length === 10 && poly[0][0] === 0 && poly[0][1] === 0, 'a sector polygon starts at the star');
    let wr = 0;
    for(let i = 1; i < poly.length; i++){
      const r = Math.hypot(poly[i][0], poly[i][1]), nu = 0.3 + (1.1 - 0.3) * (i - 1) / 8;
      wr = Math.max(wr, Math.abs(r - el.p / (1 + el.e * Math.cos(nu))));
    }
    ok(wr < 1e-12, '... and every outer vertex lies on the conic (' + wr.toExponential(2) + ')'); }
  { /* the anomaly view rides the same clock as everything else */
    withState({view: 'anom'}, () => {
      const el = buildModel().el;
      SIM.t = 0.31 * el.T;
      const A = anomModel(el);
      const want = ((el.M0 + el.n * SIM.t) % TAU + TAU) % TAU;
      close(A.M, want, 1e-12, 'the anomaly view\'s M is M0 + n t of the one clock');
      close(A.E - el.e * Math.sin(A.E), A.M, 1e-14, '... and its E solves Kepler\'s equation for it');
      close(A.t, SIM.t, 1e-15, '... at the clock\'s own time');
    }); }
  { /* a circle is handled without a periapsis direction made of noise */
    const mu = K_SUN, el = conicFromState(1.7, 0, 0, Math.sqrt(mu / 1.7), mu);
    eq(el.e, 0, 'a circular state gives e = 0 exactly');
    close(el.w, 0, 1e-15, '... with the "periapsis" put at the body');
    rel(el.a, 1.7, 1e-15, '... and a = r'); rel(el.T, periodOf(1.7, mu), 1e-15, '... and T from a'); }
  { /* the hyperbolic branch, against its own definition */
    const mu = K_SUN, el = conicFromState(2, 0, 0, 1.6 * Math.sqrt(2 * mu / 2), mu);
    eq(el.kind, 'hyperbola', 'past escape speed the conic is a hyperbola');
    ok(el.e > 1, '... with e > 1 (' + fmt(el.e, 4) + ')');
    close(el.turn, 2 * Math.asin(1 / el.e), 1e-15, '... and a turn angle 2 arcsin(1/e)');
    const s = stateOnConic(el, 0.3), el2 = conicFromState(s.x, s.y, s.vx, s.vy, mu);
    rel(el2.e, el.e, 1e-11, '... whose elements are constant along it');
    rel(0.5 * (s.vx * s.vx + s.vy * s.vy) - mu / Math.hypot(s.x, s.y), el.energy, 1e-11, '... conserving energy'); }

  /* ---------- C. the second law ---------- */
  { const el = klOrbit(2, 0, 0, V_DEF, 1, false);
    rel(el.a, REF.default_el.a, 1e-13, 'the default orbit is a = 1.5 AU (derive)');
    rel(el.e, REF.default_el.e, 1e-13, '... and e = 1/3 (derive)');
    rel(el.T, REF.default_el.T, 1e-13, '... and T (derive)');
    rel(V_DEF, REF.default_el.v0_kms, 1e-13, '... from v0 = 17.1962 km/s (derive; PhET types 17.2358 in its own mu)');
    for(const N of [2, 3, 4, 5, 6]){
      const R = REF.sectors[String(N)], cuts = klSectors(el, N), tag = 'N = ' + N + ': ';
      for(let k = 0; k <= N; k++) close(cuts[k], R.bounds[k], 1e-11, tag + 'cut ' + k + ' (derive)');
      let worstQ = 0, worstC = 0;
      for(let k = 0; k < N; k++){
        const A = sectorArea(el, cuts[k], cuts[k + 1]);
        const Aq = sectorAreaQuad(el, cuts[k], cuts[k + 1], 32);
        worstC = Math.max(worstC, Math.abs(A - R.area) / R.area);
        worstQ = Math.max(worstQ, Math.abs(Aq - A) / R.area);
      }
      ok(worstC < 1e-13, tag + 'every sector has area pi a b / N in closed form (' + worstC.toExponential(2) + ')');
      ok(worstQ < 1e-12, tag + 'and by quadrature of 1/2 r^2 dnu, which knows nothing of Kepler\'s equation (' + worstQ.toExponential(2) + ')');
      rel(el.T / N, R.dt, 1e-13, tag + 'each takes T/N (derive)');
    }
    /* the swept area over an interval is 1/2 h dt */
    const t1 = REF.sweep_check.t1, t2 = REF.sweep_check.t2;
    const s1 = klStateAt(el, t1), s2 = klStateAt(el, t2);
    const A = sectorArea(el, trueFromE(s1.E, el.e), trueFromE(s2.E, el.e));
    rel(A, REF.sweep_check.closed, 1e-12, 'the area swept between two times is 1/2 |h| dt (derive)');
    rel(A, REF.sweep_check.shoelace, 1e-7, '... and the shoelace of a 20,001-gon of that region (derive)');
    rel(0.5 * Math.abs(el.h) * (t2 - t1), A, 1e-13, '... the two forms agree here too');
    /* the sweep bookkeeping */
    const full = klSwept(el, 4, 0, {erased: false, tErase: 0});
    ok(full.frac.every(f => f === 1), 'before the clock runs every sector shows its full area');
    /* the planet starts at apoapsis (M0 = pi), so the sectors fill from there.  The invariant:
       what is painted is the mean anomaly swept since the erase, counted from the cut the
       planet was at or behind -- PhET fills a sector from its own cut, not from the planet. */
    const sweepCheck = (N, t, tErase) => {
      const w = klSwept(el, N, t, {erased: true, tErase}), D = TAU / N;
      const Me = el.M0 + el.n * tErase, Mn = el.M0 + el.n * t, je = Math.floor(Me / D);
      const painted = w.frac.reduce((a, b2) => a + b2, 0) * D;
      return {w, painted, want: Math.min(Mn - je * D, TAU), partial: w.frac.filter(f => f > 0 && f < 1).length};
    };
    const q = sweepCheck(4, el.T * 0.30, 0);
    close(q.painted, q.want, 1e-12, 'a third of the way round, the painted area is the mean anomaly swept from the last cut');
    eq(q.partial, 1, '... with exactly one sector part way');
    eq(q.w.frac.filter(f => f === 1).length, 1, '... and one finished');
    const q2 = sweepCheck(6, el.T * 0.77, 0);
    close(q2.painted, q2.want, 1e-12, 'three quarters of the way round, the same identity holds at N = 6');
    const done = klSwept(el, 4, el.T, {erased: true, tErase: 0});
    ok(done.frac.every(f => f === 1), 'after one period every sector is full again');
    rel(done.frac.reduce((a, b2) => a + b2, 0) * done.full, PI * el.a * el.b, 1e-13, 'and their areas add to the whole ellipse');
    const q3 = sweepCheck(5, el.T * 0.61, el.T * 0.2);
    close(q3.painted, q3.want, 1e-12, 'erasing mid-orbit starts the filling from the cut behind the planet (PhET\'s rule)');
    eq(q3.w.frac.filter(f => f === 0).length, 2, '... leaving the sectors it has not reached empty'); }

  /* ---------- D. the third law ---------- */
  for(const key in REF.targets){
    const R = REF.targets[key], T = periodOf(R.a, starMu(1));
    rel(T, R.T, 1e-14, key + ': T = 2 pi sqrt(a^3/GM) (derive)');
    rel(T * T / Math.pow(R.a, 3), REF.kepler_const, 1e-13, key + ': T^2/a^3 is the same constant');
    rel(auYrToKms(Math.sqrt(starMu(1) * (1 + R.e) / (R.a * (1 - R.e)))), R.vq_kms, 1e-12, key + ': periapsis speed (derive)');
  }
  for(const m of [0.5, 1.0, 1.5, 2.0]){
    rel(klConst(m), TAU * TAU / (K_SUN * m), 1e-15, 'the third-law constant at ' + m + ' M_sun');
    rel(starRadius(m), REF.star_radius[m.toFixed(1)], 1e-14, 'PhET\'s star radius at ' + m + ' M_sun (derive)');
  }
  eq(massToRadius(1e-9), 0.03, 'PhET\'s radius rule has a 0.03 AU floor');
  { const slope = (Math.log10(periodOf(4, K_SUN)) - Math.log10(periodOf(1, K_SUN))) / Math.log10(4);
    close(slope, 1.5, 1e-14, 'on log-log the slope is exactly 3/2');
    const slope2 = (Math.log10(periodOf(4, K_SUN * 2)) - Math.log10(periodOf(1, K_SUN * 2))) / Math.log10(4);
    close(slope2, 1.5, 1e-14, '... whatever the star\'s mass');
    ok(periodOf(1, K_SUN * 2) < periodOf(1, K_SUN), '... though a heavier star shifts the line down'); }
  { const el = klOrbit(2, 0, 0, V_DEF, 1, false), th = klThird(el, 3, 2);
    ok(th.correct, 'a^3 with T^2 is the right pair');
    rel(th.ratio, klConst(1), 1e-12, '... and its value is 4 pi^2/GM');
    ok(!klThird(el, 2, 2).correct && !klThird(el, 3, 3).correct, 'no other pair is'); }

  /* ---------- E. PhET's rules ---------- */
  { const el = klOrbit(2, 0, 0, auYrToKms(0.99 * Math.sqrt(2 * K_SUN / 2)), 1, false);
    rel(el.a, REF.escape.cap_a, 1e-11, 'at PhET\'s 0.99 escape cap: a = 50.25 AU (derive)');
    rel(el.e, REF.escape.cap_e, 1e-12, '... e = 0.9602 (derive)');
    ok(el.escaping && !el.allowed, '... and the orbit is flagged, so the clock will not run');
    const over = klOrbit(2, 0, 0, auYrToKms(3 * Math.sqrt(2 * K_SUN / 2)), 1, false);
    rel(over.vKms, auYrToKms(0.99 * Math.sqrt(2 * K_SUN / 2)), 1e-12, 'a faster drag is capped at 0.99 v_esc, as PhET caps it');
    eq(over.kind, 'ellipse', '... so the orbit stays an ellipse');
    const just = klOrbit(2, 0, 0, auYrToKms(0.97 * Math.sqrt(2 * K_SUN / 2)), 1, false);
    ok(!just.escaping && just.allowed, 'below 0.9801 v_esc the orbit is allowed');
    rel(just.vescKms, REF.escape.vesc_kms, 1e-13, 'the escape speed at 2 AU (derive)'); }
  { const el = klOrbit(2, 0, 0, REF.escape.v_crash_kms, 1, false);
    rel(el.q, REF.escape.R1, 1e-9, 'the crash boundary: periapsis at the star\'s radius (derive)');
    const inside = klOrbit(2, 0, 0, REF.escape.v_crash_kms * 0.98, 1, false);
    ok(inside.crash && !inside.allowed, 'a little slower and it crashes, as PhET flags it');
    ok(!el.crash || el.q <= el.star, 'the crash test is periapsis against the star radius'); }
  { const el = klOrbit(2, 0, 0, V_DEF, 1, true);
    close(el.e, 0, 1e-12, '"hold circular" gives a circle');
    rel(el.a, 2, 1e-12, '... of radius r');
    rel(el.vKms, auYrToKms(Math.sqrt(K_SUN / 2)), 1e-12, '... at the circular speed'); }
  { const el = klOrbit(0, 0, 0, 20, 1, false); ok(isFinite(el.a) && el.r > 0, 'a planet dropped on the star is nudged off it (PhET\'s rule)'); }
  { /* PhET's clock and its own mu, re-derived */
    rel(PHET.FRAME_YR, REF.frame_yr, 1e-15, 'one frame at normal speed is PhET\'s 1/378 yr (derive)');
    rel(PHET.CLOCK / TAU, REF.phet.clock / TAU, 1e-15, 'PhET advances 6.3/T rad per year, not 2 pi/T (derive)');
    rel(TAU / PHET.CLOCK, REF.phet.rev_reads, 1e-14, '... so one revolution reads 0.99733 T on its stopwatch (derive)');
    rel(Math.sqrt(PHET.MU_NORM), REF.phet.vcirc1, 1e-12, 'PhET\'s circular speed at 1 AU is 29.855 km/s (derive)');
    rel(REF.phet.vratio, Math.sqrt(PHET.MU_NORM) / (TAU * KMS), 1e-12, '... 0.24 % from 2 pi AU in its own 1-yr period (derive)');
    rel(PHET.MU_COEFF * PHET.SUN, REF.phet.mu, 1e-15, 'PhET\'s mu = 4.45669 x 200 (derive)'); }

  /* ---------- F. the clock, the model and the readouts ---------- */
  { const el = klOrbit(2, 0, 0, V_DEF, 1, false);
    withState({}, () => {
      eq(SIM.t, 0, 'a fresh state starts at t = 0');
      ok(!runStep(), 'the clock does not run while paused');
      setRunning(true); ok(runStep(), 'it runs when told to');
      close(SIM.t, frameDt(), 1e-18, 'one frame advances frameDt');
      ok(SIM.sweep.erased, 'pressing play erases the sectors, as PhET does');
      ST.speed = 'fast'; const t0 = SIM.t; runStep();
      close(SIM.t - t0, PHET.FRAME_YR * 1.75, 1e-18, 'fast is 7/4 of normal (PhET\'s timeSpeedMap)');
      ST.speed = 'slow'; const t1 = SIM.t; runStep();
      close(SIM.t - t1, PHET.FRAME_YR * 0.25, 1e-18, 'slow is 1/4');
      ST.stopwatch = true; SIM.swRun = true; const s0 = SIM.sw; runStep();
      close(SIM.sw - s0, frameDt(), 1e-18, 'the stopwatch runs with the clock');
    });
    withState({vy: auYrToKms(0.995 * Math.sqrt(K_SUN)), px: 2, py: 0}, () => {
      setRunning(true); ok(!runStep(), 'an escaping orbit does not run (PhET disables play)'); });
    withState({}, () => { setRunning(true); for(let k = 0; k < 40; k++) runStep();
      const M = buildModel();
      rel(M.now.r, klStateAt(el, SIM.t).r, 1e-12, 'the planet is where Kepler puts it after 40 frames');
      ok(M.sec === undefined, 'the first law view does not build the second law\'s model'); }); }
  /* every view x a spread of states: the panels must be clean */
  const CFG = [['default', {}], ['circular', {circular: true}], ['eccentric', {px: 0.6, py: 0, vx: 0, vy: 50}],
               ['heavy star', {mass: 1.8}], ['light star', {mass: 0.5}], ['clockwise', {vy: -V_DEF}],
               ['target earth', {target: 'earth'}], ['target jupiter', {target: 'jupiter', zoom: 'far'}],
               ['escaping', {vy: auYrToKms(0.995 * Math.sqrt(K_SUN))}], ['crashing', {vy: 3}],
               ['divisions 6', {div: 6, areaVals: true, timeVals: true}], ['running', {frames: 60}],
               ['powers 3,2', {pa: 3, pt: 2}], ['loglog', {loglog: true}], ['all on', {foci: true, string: true, axes: true,
                 semiaxes: true, ecc: true, apo: true, peri: true, grid: true, tape: true, stopwatch: true,
                 gravity: true, speedLab: true, showT: true}]];
  for(const [v] of TABS) for(const [nm, over] of CFG){
    const html = withState(Object.assign({view: v}, over), () => {
      const M = buildModel(); return readoutHTML(M) + eqbarHTML(M) + tagHTML(M);
    });
    ok(html.indexOf('NaN') < 0 && html.indexOf('undefined') < 0 && html.indexOf('Infinity') < 0 && html.indexOf('null') < 0,
       'panels clean for ' + v + ' / ' + nm);
  }
  { const r = withState({}, () => readoutHTML(buildModel()));
    ok(r.indexOf('1.5000') >= 0, 'the readout prints a = 1.5000 AU for the default orbit');
    ok(r.indexOf('our Sun') >= 0, 'and names our Sun');
    const r2 = withState({view: 'second', div: 5}, () => readoutHTML(buildModel()));
    ok(r2.indexOf(sigf(PI * 1.5 * 1.5 * Math.sqrt(1 - 1 / 9) / 5, 6)) >= 0, 'the second-law readout prints pi a b / 5');
    const r3 = withState({view: 'third', pa: 3, pt: 2}, () => readoutHTML(buildModel()));
    ok(r3.indexOf(fmt(klConst(1), 5)) >= 0, 'the third-law readout prints 4 pi^2/GM');
    const r4 = withState({vy: 3}, () => readoutHTML(buildModel()));
    ok(r4.indexOf('crash') >= 0, 'a crashing orbit says so'); }

  /* ---------- G. the scene and the drags ---------- */
  { const shot = makeShot(1400, 820);
    const S = makeScene({getContext: () => shot});
    S.W = 1400; S.H = 820;
    Object.assign(ST, DEFAULTS); simReset();
    ok(!S.step(), 'nothing moves while the clock is paused');
    setRunning(true); ok(S.step(), 'and does when it runs');
    setRunning(false); simReset();
    const b = mainBox(shot, S.W, S.H, 'first'), map = orbitMap(b, viewRadius());
    const PX = map.X(ST.px), PY = map.Y(ST.py);
    ok(S.pointer('down', PX, PY), 'pointer-down on the planet grabs it');
    eq(DRAGK.what, 'planet', '... as a planet drag');
    ok(S.pointer('move', PX - 40, PY), '... and the move is taken');
    ok(ST.px < 2 - 0.1, 'dragging left moves the planet in (' + fmt(ST.px, 3) + ' AU)');
    eq(SIM.t, 0, '... and restarts its clock');
    ok(S.pointer('up', 0, 0), 'pointer-up lets go');
    Object.assign(ST, DEFAULTS); simReset();
    const TX = map.X(ST.px) + ST.vx * VSCALE, TY = map.Y(ST.py) - ST.vy * VSCALE;
    ok(S.pointer('down', TX, TY), 'pointer-down on the arrow tip grabs the velocity');
    eq(DRAGK.what, 'vel', '... as a velocity drag');
    S.pointer('move', TX, TY + 30);
    ok(ST.vy < V_DEF - 5, 'dragging the tip down slows it (' + fmt(ST.vy, 2) + ' km/s)');
    const el = klOrbit(ST.px, ST.py, ST.vx, ST.vy, ST.mass, ST.circular);
    ok(el.a < 1.5, '... which shrinks the orbit (a = ' + fmt(el.a, 3) + ' AU)');
    S.pointer('up', 0, 0);
    Object.assign(ST, DEFAULTS); simReset();
    S.pointer('down', map.X(ST.px), map.Y(ST.py)); S.pointer('move', map.X(0), map.Y(0)); S.pointer('up', 0, 0);
    ok(Math.hypot(ST.px, ST.py) >= starRadius(1) * 1.39, 'the planet cannot be dragged into the star');
    Object.assign(ST, DEFAULTS); ST.tape = true; simReset();
    ok(S.pointer('down', map.X(SIM.tape.bx), map.Y(SIM.tape.by)), 'the tape\'s tip can be grabbed');
    S.pointer('move', map.X(2.5), map.Y(-1)); S.pointer('up', 0, 0);
    close(SIM.tape.bx, 2.5, 1e-9, '... and dragged to where the pointer is');
    Object.assign(ST, DEFAULTS); ST.view = 'anom'; simReset();
    ok(!S.pointer('down', map.X(2), map.Y(0)), 'the anomaly view takes no drags (its slider is the control)');
    Object.assign(ST, stSave); simReset(); }

  /* ---------- H. layout sweep ---------- */
  const SIZES = [[1400, 820], [1100, 700], [820, 520], [560, 380]];
  const LAY = [
    ['first', {view: 'first'}, 8], ['first all on', {view: 'first', foci: true, string: true, axes: true, semiaxes: true,
      ecc: true, grid: true, tape: true, stopwatch: true, gravity: true}, 10],
    ['first target', {view: 'first', target: 'mars'}, 8], ['first escaping', {view: 'first', vy: auYrToKms(0.995 * Math.sqrt(K_SUN))}, 6],
    ['first crashing', {view: 'first', vy: 3}, 6],
    ['second', {view: 'second'}, 10], ['second 6 running', {view: 'second', div: 6, areaVals: true, timeVals: true, frames: 90}, 10],
    ['second 2', {view: 'second', div: 2, apo: true, peri: true}, 10],
    ['third', {view: 'third'}, 6], ['third 3,2', {view: 'third', pa: 3, pt: 2}, 6],
    ['third loglog', {view: 'third', loglog: true, zoom: 'far'}, 6], ['third jupiter', {view: 'third', target: 'jupiter', zoom: 'far'}, 6],
    ['all', {view: 'all'}, 10], ['all everything', {view: 'all', foci: true, string: true, axes: true, semiaxes: true,
      ecc: true, apo: true, peri: true, showT: true, frames: 40}, 12],
    ['anom', {view: 'anom'}, 8], ['anom high e', {view: 'anom', px: 0.6, py: 0, vx: 0, vy: 50}, 8],
    ['anom circular', {view: 'anom', circular: true}, 8]
  ];
  const entRe = /&#?[a-zA-Z0-9]+;|<[a-zA-Z][^>]*>/;
  for(const [nm, over, minFills] of LAY) for(const [W, H] of SIZES){
    withState(over, () => {
      const c = makeShot(W, H); let err = null;
      try{ drawView(c, W, H, buildModel()); }catch(e){ err = e; }
      ok(!err, nm + ' ' + W + 'x' + H + ' draws without throwing' + (err ? ': ' + (err.stack || err) : ''));
      if(err) return;
      const texts = c.ops.filter(o => o.op === 'text'), fills = c.ops.filter(o => o.op === 'fill');
      ok(fills.length >= minFills && texts.length >= 1, nm + ' ' + W + 'x' + H + ' draws substance (' + fills.length + ' fills, floor ' + minFills + ')');
      let bad = null;
      for(const t of texts){
        if(entRe.test(t.t)){ bad = 'entity/tag: "' + t.t.slice(0, 40) + '"'; break; }
        if(/undefined|NaN/.test(t.t)){ bad = 'NaN/undefined: "' + t.t.slice(0, 40) + '"'; break; }
        if(t.bb[0] < -1 || t.bb[2] > W + 1 || t.bb[1] < -1 || t.bb[3] > H + 1){ bad = 'off-canvas: "' + t.t.slice(0, 30) + '" [' + t.bb.map(v => fmt(v, 0)) + ']'; break; }
      }
      ok(!bad, nm + ' ' + W + 'x' + H + ' text clean (' + (bad || 'ok') + ')');
      /* the house #hint (HTML, bottom:11px) owns the bottom-left corner */
      const inHint = texts.filter(t => t.bb[0] < 340 && t.bb[3] > H - 27);
      ok(!inHint.length, nm + ' ' + W + 'x' + H + ' no canvas text under the #hint line'
         + (inHint.length ? ' ("' + inHint[0].t.slice(0, 30) + '" to y ' + fmt(inHint[0].bb[3], 0) + ')' : ''));
      let hit = null;
      for(let i = 0; i < texts.length && !hit; i++) for(let j = i + 1; j < texts.length; j++){
        const a = texts[i].bb, b2 = texts[j].bb;
        const ox = Math.min(a[2], b2[2]) - Math.max(a[0], b2[0]), oy = Math.min(a[3], b2[3]) - Math.max(a[1], b2[1]);
        if(ox > 3 && oy > 3){ hit = '"' + texts[i].t.slice(0, 22) + '" vs "' + texts[j].t.slice(0, 22) + '"'; break; }
      }
      ok(!hit, nm + ' ' + W + 'x' + H + ' no text collisions (' + (hit || 'ok') + ')');
      let leg = null;
      for(const r of LEGEND_RECTS) for(let i = 0; i < POLY_SEGS.length; i += 4){
        const x0 = POLY_SEGS[i], y0 = POLY_SEGS[i + 1], x1 = POLY_SEGS[i + 2], y1 = POLY_SEGS[i + 3];
        if(Math.max(x0, x1) < r.x || Math.min(x0, x1) > r.x + r.w || Math.max(y0, y1) < r.y || Math.min(y0, y1) > r.y + r.h) continue;
        leg = 'a curve crosses the legend'; break;
      }
      ok(!leg, nm + ' ' + W + 'x' + H + ' legend clear');
    });
  }

  const dt = (Date.now() - T0) / 1000;
  console.log(pass + ' passed, ' + fail + ' failed  (' + fmt(dt, 1) + ' s)');
  if(fail > 0) throw new Error(fail + ' self-test failure(s)');
  return fail;
}

/* ============================== entry ============================= */
if(typeof document === 'undefined'){
  selfTest();
} else {
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
}
